from argparse import ArgumentParser

def parse_csv(input_csv):
    reader = csv.DictReader(input_csv)
    times = {}
    for row in reader:
        athlete = row['athlete']
        seconds = float(row['seconds'])
        if athlete not in times or seconds < times[athlete]:
            times[athlete] = seconds
    return times

def filter_times(times, under=None):
    if under is None:
        return times
    return {athlete: time for athlete, time in times.items() if time < under}

def main():
    parser = ArgumentParser(description='CLI for running split times')
    parser.add_argument('--under', type=float, help='Filter out times at or above this limit')
    args = parser.parse_args()

    if not sys.stdin.isatty():
        input_csv = sys.stdin
    else:
        print("Please provide CSV input via stdin.")
        return

    times = parse_csv(input_csv)
    filtered_times = filter_times(times, args.under)

    print(json.dumps(filtered_times, indent=4))

